mapper.select:
/* TransactionMapper.selectTransOdList */ SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
SELECT od.OD_JOB_NO , CASE WHEN gov.RECV_RES_CODE != '0000' THEN '오류' WHEN gov.RECV_RES_CODE = '0000' THEN '접수' WHEN gov.SEND_RES_CODE != '0000' THEN '전송오류' WHEN gov.SEND_RES_CODE = '0000' THEN '전송' ELSE '준비' END AS LAST_POD_STATUS , od.CUST_CODE_LV1 , od.CUST_CODE_LV2 , gov.SEND_DATE_TIME
, od.HBL_NO , od.ECM_BUY_TYPE , od.ORIG_COUNTRY , od.AGENT_REG_NO , od.AGENT_NAME , od.FORWARD_AGENT_CODE , od.FORWARD_AGENT_NAME , od.SHIPPER_NAME , od.SHIPPER_ADDRESS , od.SHIPPER_TEL , od.ORDER_END_DATETIME , od.ORDER_NAME , od.ORDER_TEL , od.ORDER_ACCOUNT , od.CONSIGNEE_NAME_LOC , od.CONSIGNEE_TEL , od.CONSIGNEE_ZIPCODE , od.CONSIGNEE_ADDRESS_LOC , od.REGISTER_DATE_TIME , gov.EC_IF_SBMT_NO , CONVERT(VARCHAR(MAX), gov.RECV_ERR_CN, 2) AS RECV_ERR_CN FROM TB_ECM_OD od INNER JOIN TB_ECM_OD_ADDITIONAL oa ON od.OD_JOB_NO = oa.OD_JOB_NO LEFT JOIN TB_EDI_GOV_ECOMMERCE gov ON oa.EC_IF_SBMT_NO = gov.EC_IF_SBMT_NO WHERE od.ENT_CODE = #{srchEntCode}
AND ${srchNoType} IN (#{item})
AND ${srchNoType} LIKE CONCAT(#{srchNo},'%')
AND ${srchDateGbn} >= CONVERT(DATE, #{srchStartDate}, ${srchDateFormat}) AND ${srchDateGbn} < DATEADD(DAY, 1, CONVERT(DATE, #{srchEndDate}, ${srchDateFormat})) AND oa.LAST_POD_STATUS = 'ECM002' AND od.ECM_GOV_SEND_YN = 'Y'
AND ${srchCusType} = #{srchCuslv1}
AND ${srchCusType} = #{srchCuslv2}
AND od.CUST_CODE_LV${loginCustomerLev} = #{loginCustomerCd}
AND od.BOUND = 'AIR' AND od.BOUND_TYPE = 'IMP' AND od.BOUND = 'SEA' AND od.BOUND_TYPE = 'IMP'
AND (gov.SEND_RES_CODE IS NOT NULL AND gov.SEND_RES_CODE <> '') AND (gov.SEND_RES_CODE IS NULL OR gov.SEND_RES_CODE = '')

/* TransactionMapper.selectTransItemList */ SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
SELECT od.OD_JOB_NO , item.SEQ_NO_ID , item.ORDER_NO , item.CUSTOMS_ID , item.CUSTOMS_TEMP_NO , item.CUSTOMS_ID_VERIFY , CASE WHEN ISNULL(item.CUSTOMS_TEMP_NO, '') <> '' THEN 'Y' ELSE 'N' END AS CUSTOMS_TEMP_NO_YN , item.ITEM_NO , item.CATEGORY_NAME_1 , item.CATEGORY_NAME_2 , item.HS_CODE , item.DETAIL_ITEM_NAME , item.ECM_URL , item.PIECES , item.UNIT_PRICE , item.CURRENCY_CODE , item.AMOUNT_CUR , item.CURRENCY_CODE AS AMOUNT_CURRENCY_CODE FROM TB_ECM_OD od INNER JOIN TB_ECM_OD_ADDITIONAL oa ON od.OD_JOB_NO = oa.OD_JOB_NO INNER JOIN TB_ECM_OD_ITEM item ON od.OD_JOB_NO = item.OD_JOB_NO LEFT JOIN TB_EDI_GOV_ECOMMERCE gov ON oa.EC_IF_SBMT_NO = gov.EC_IF_SBMT_NO WHERE od.ENT_CODE = #{srchEntCode}
AND od.OD_JOB_NO = #{srchNo}
AND ${srchDateGbn} >= CONVERT(DATE, #{srchStartDate}, ${srchDateFormat}) AND ${srchDateGbn} < DATEADD(DAY, 1, CONVERT(DATE, #{srchEndDate}, ${srchDateFormat}))

/* TransactionMapper.selectTransOdJobNoList */
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
SELECT
	od.OD_JOB_NO
FROM 
	TB_ECM_OD_ADDITIONAL oa
	INNER JOIN TB_ECM_OD od ON oa.OD_JOB_NO = od.OD_JOB_NO
WHERE oa.EC_IF_SBMT_NO = #{ecIfSbmtNo}

mapper.delete:
/* TransactionMapper.deleteTransactionOd : 거래정보 오더 정보 삭제 */
DELETE FROM TB_ECM_OD WHERE OD_JOB_NO = #{odJobNo};
DELETE FROM TB_ECM_OD_ADDITIONAL WHERE OD_JOB_NO = #{odJobNo};
DELETE FROM TB_ECM_OD_ITEM WHERE OD_JOB_NO = #{odJobNo};
DELETE FROM TB_ECM_POD WHERE OD_JOB_NO = #{odJobNo};
DELETE FROM TB_ECM_POD_01 WHERE OD_JOB_NO = #{odJobNo};
DELETE FROM TB_ECM_POD_02 WHERE OD_JOB_NO = #{odJobNo};
DELETE FROM TB_ECM_POD_03 WHERE OD_JOB_NO = #{odJobNo};
DELETE FROM TB_ECM_POD_04 WHERE OD_JOB_NO = #{odJobNo};
DELETE FROM TB_ECM_OD_MULTI WHERE OD_JOB_NO = #{odJobNo};
DELETE FROM TB_ECM_OD_LICENSE WHERE OD_JOB_NO = #{odJobNo};

 		/* TransactionMapper.deleteTransactionInfo : 거래정보 테이블 정보 삭제 */
		DELETE FROM TB_EDI_GOV_ECOMMERCE
		WHERE ENT_CODE = #{entCode}
		AND EC_IF_SBMT_NO = #{ecIfSbmtNo}

mapper.select:
/* TransactionMapper.selectTransOdExcelList */ SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
SELECT
od.OD_JOB_NO AS odJobNo , CASE WHEN gov.EC_IF_SBMT_NO != '' AND gov.EC_IF_SBMT_NO IS NOT NULL THEN '전송' WHEN gov.SEND_RES_CODE != 'S' THEN '전송오류' WHEN gov.SEND_RES_CODE = 'S' THEN '수신대기' WHEN gov.RECV_STATUS = 'S' THEN '접수' WHEN gov.RECV_STATUS != 'S' THEN '오류' ELSE '' END AS lastPodStatus , od.CUST_CODE_LV1 AS custCodeLv1 , od.CUST_CODE_LV2 AS custCodeLv2 , gov.SEND_DATE_TIME AS sendDateTime
, od.HBL_NO AS hblNo , od.ECM_BUY_TYPE AS ecmBuyType , od.ORIG_COUNTRY AS origCountry , od.AGENT_REG_NO AS agentRegNo , od.AGENT_NAME AS agentName , od.FORWARD_AGENT_CODE AS forwardAgentCode , od.FORWARD_AGENT_NAME AS forwardAgentName , od.SHIPPER_NAME AS shipperName , od.SHIPPER_ADDRESS AS shipperAddress , od.SHIPPER_TEL AS shipperTel , od.ORDER_END_DATETIME AS orderEndDatetime , od.ORDER_NAME AS orderName , od.ORDER_TEL AS orderTel , od.ORDER_ACCOUNT AS orderAccount , od.CONSIGNEE_NAME_LOC AS consigneeNameLoc , od.CONSIGNEE_TEL AS consigneeTel , od.CONSIGNEE_ZIPCODE AS consigneeZipcode , od.CONSIGNEE_ADDRESS_LOC AS consigneeAddressLoc , od.REGISTER_DATE_TIME AS registerDateTime , item.SEQ_NO_ID AS seqNoId , item.ORDER_NO AS orderNo , item.CUSTOMS_ID AS customsId , item.CUSTOMS_TEMP_NO AS customsTempNo , (SELECT NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE GROUP_CODE = 'CUSTOMS_ID_VERIFY' AND CODE = item.CUSTOMS_ID_VERIFY) AS customsIdVerify , CASE WHEN ISNULL(item.CUSTOMS_TEMP_NO, '') <> '' THEN 'Y' ELSE 'N' END AS customsTempNoYn , item.ITEM_NO AS itemNo , item.CATEGORY_NAME_1 AS categoryName1 , item.CATEGORY_NAME_2 AS categoryName2 , item.HS_CODE AS hsCode , item.DETAIL_ITEM_NAME AS detailItemName , item.ECM_URL AS ecmUrl , item.PIECES AS pieces , item.UNIT_PRICE AS unitPrice , item.CURRENCY_CODE AS currencyCode , item.AMOUNT_CUR AS amountCur , item.CURRENCY_CODE AS amountCurrencyCode FROM TB_ECM_OD od INNER JOIN TB_ECM_OD_ADDITIONAL oa ON od.OD_JOB_NO = oa.OD_JOB_NO INNER JOIN TB_ECM_OD_ITEM item ON od.OD_JOB_NO = item.OD_JOB_NO LEFT JOIN TB_EDI_GOV_ECOMMERCE gov ON oa.EC_IF_SBMT_NO = gov.EC_IF_SBMT_NO WHERE od.ENT_CODE = #{srchEntCode}
AND od.OD_JOB_NO IN (#{item.odJobNo})
AND ${srchNoType} IN (#{item})
AND ${srchNoType} LIKE CONCAT(#{srchNo},'%')
AND ${srchDateGbn} >= CONVERT(DATE, #{srchStartDate}, ${srchDateFormat}) AND ${srchDateGbn} < DATEADD(DAY, 1, CONVERT(DATE, #{srchEndDate}, ${srchDateFormat}))
AND ${srchCusType} = #{srchCuslv1}
AND ${srchCusType} = #{srchCuslv2}
AND od.CUST_CODE_LV${loginCustomerLev} = #{loginCustomerCd}
AND oa.LAST_POD_STATUS = 'ECM002' AND od.ECM_GOV_SEND_YN = 'Y'
AND od.BOUND = 'AIR' AND od.BOUND_TYPE = 'IMP' AND od.BOUND = 'SEA' AND od.BOUND_TYPE = 'IMP'
AND (gov.SEND_RES_CODE IS NOT NULL AND gov.SEND_RES_CODE <> '') AND (gov.SEND_RES_CODE IS NULL OR gov.SEND_RES_CODE = '')

/* TransactionMapper.selectChkTransCustomsInfo */ SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED; SELECT
od.HBL_NO AS hbl_no , item.ORDER_NO AS ord_no , od.ORDER_NAME AS ordrr_fnm , od.ORDER_TEL AS ordrr_telno , od.CONSIGNEE_NAME_LOC AS cnsi_fnm , od.CONSIGNEE_TEL AS cnsi_telno , od.CONSIGNEE_ZIPCODE AS dlvrpl_psno , item.CUSTOMS_TEMP_NO AS su_crtf_no , item.CUSTOMS_ID AS cnsi_pers_ecm , item.ECM_GOV_REQ_NO AS ecm_gov_req_no
FROM TB_ECM_OD od INNER JOIN ( SELECT MAX(OD_JOB_NO) AS OD_JOB_NO , ORDER_NO , ECM_GOV_REQ_NO , MAX(CUSTOMS_ID) AS CUSTOMS_ID , MAX(CUSTOMS_TEMP_NO) AS CUSTOMS_TEMP_NO FROM TB_ECM_OD_ITEM WHERE OD_JOB_NO = #{odJobNo} GROUP BY ORDER_NO, ECM_GOV_REQ_NO ) item ON od.OD_JOB_NO = item.OD_JOB_NO WHERE od.OD_JOB_NO = #{odJobNo}

/* TransactionMapper.selectCustomerInfo */
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
SELECT
	cus.PARENT_CUSTOMER_CODE AS parentCustomerCode
	, ci.IF_ETC_1 AS commBusinessCode
	, ci.IF_ETC_2 AS clientId
	, ci.IF_ETC_3 AS clientSecret
FROM
	TB_SMS_CUSTOMER cus
	LEFT JOIN TB_SMS_CUSTOMER_INTERFACE ci ON cus.ENT_CODE = ci.ENT_CODE AND cus.CUSTOMER_CODE = ci.CUSTOMER_CODE AND ci.IF_SERVICE_CODE = 'ECM_GOV_SIGN'
WHERE 
	cus.ENT_CODE = #{entCode}
	AND cus.CUSTOMER_CODE = #{customerCd}

mapper.update:
/* TransactionMapper.updateCheckCustomsId : 개인통관고유번호 검증 결과 업데이트 */
UPDATE TB_ECM_OD_ITEM
SET CUSTOMS_ID_VERIFY = #{resCode}

	, ECM_GOV_REQ_NO = #{reqNo}


	, CUSTOMS_TEMP_NO = #{customsTempNo}

WHERE OD_JOB_NO = #{odJobNo}
AND ORDER_NO = #{ord_no}
